namespace WallstopStudios.UnityHelpers.Tests.Editor.Capture
{
#if UNITY_EDITOR && UNITY_6000_0_OR_NEWER
    using System;
    using System.Collections;
    using System.IO;
    using System.Reflection;
    using NUnit.Framework;
    using UnityEditor;
    using UnityEngine;
    using UnityEngine.UIElements;
    using WallstopStudios.UnityHelpers.Tests.Core;
    using WallstopStudios.UnityHelpers.Tests.EditorFramework;

    [TestFixture]
    public sealed class BuildProfileSettingsCaptureTests : CommonTestBase
    {
        [Test]
        public void CaptureSettings()
        {
            Assert.IsTrue(EditorSurfaceCapture.IsSupported, EditorSurfaceCapture.UnsupportedReason);
            string output = Environment.GetEnvironmentVariable("UH_BUILD_PROFILE_CAPTURE_OUTPUT");
            Assert.IsFalse(string.IsNullOrWhiteSpace(output));
            MethodInfo discover = typeof(SettingsService).GetMethod(
                "FetchSettingsProviders",
                BindingFlags.NonPublic | BindingFlags.Static,
                null,
                Type.EmptyTypes,
                null
            );
            Assert.IsTrue(discover != null);
            SettingsProvider[] providers = discover.Invoke(null, null) as SettingsProvider[];
            Assert.IsTrue(providers != null);
            SettingsProvider selected = null;
            foreach (SettingsProvider provider in providers)
            {
                if (provider.settingsPath == "Project/Wallstop Studios/Unity Helpers")
                {
                    selected = provider;
                    break;
                }
            }
            Assert.IsTrue(selected != null);
            Assert.IsTrue(selected.guiHandler != null);
            VisualElement surface = new();
            surface.style.width = 1100;
            surface.style.height = 850;
            surface.style.backgroundColor = EditorGUIUtility.isProSkin
                ? new Color(0.22f, 0.22f, 0.22f)
                : new Color(0.76f, 0.76f, 0.76f);
            int calls = 0;
            IMGUIContainer content = new(() =>
            {
                ++calls;
                selected.guiHandler(string.Empty);
            });
            content.style.width = 1080;
            content.style.marginLeft = 10;
            content.style.marginTop = 10;
            surface.Add(content);
            EditorSurfaceCaptureResult? captured = null;
            IEnumerator context = TestIMGUIExecutor.Run(
                () =>
                {
                    if (Event.current.type == EventType.Repaint)
                    {
                        captured = EditorSurfaceCapture.Capture(surface, 1100, 850, output);
                    }
                },
                TestIMGUIExecutorBudget.Default,
                strictLogs: true
            );
            Assert.IsFalse(context.MoveNext());
            Assert.IsTrue(captured.HasValue);
            EditorSurfaceCaptureResult result = captured.Value;
            TestContext.WriteLine($"GUI draws={calls}; colors={result.DistinctColorCount}");
            Assert.Less(16, result.DistinctColorCount);
            Assert.IsTrue(result.OnlyCursorRectErrors, result.RenderErrorSummary);
            File.WriteAllText(output + ".txt", result.ToString());
        }
    }
#endif
}

