$ErrorActionPreference = 'Stop'
$repository = [IO.Path]::GetFullPath((Join-Path $PSScriptRoot '../../..'))
$project = Join-Path ([IO.Path]::GetTempPath()) 'uh-session-20261114-morning-validation'
$pwsh = Join-Path $env:USERPROFILE 'scoop/apps/pwsh/current/pwsh.exe'
$paths=@{settings='Editor/Settings/UnityHelpersSettings.cs';sync='Editor/Tools/BuildProfileSceneSync.cs';tests='Tests/Editor/Tools/BuildProfileSceneSyncTests.cs'}
