@{pid=$PID;startUtc=[DateTime]::UtcNow}|ConvertTo-Json|Set-Content(Join-Path $PSScriptRoot 'capture-settings-gui-scope-identity.json')
function Install-Phase([string]$phase) {
 foreach($name in $paths.Keys){
  $target=Join-Path $repository $paths[$name]
  $current=(Get-FileHash $target).Hash
  $allowed=@('before','after')|ForEach-Object {(Get-FileHash(Join-Path $PSScriptRoot "capture-$name-$_.cs.txt")).Hash}
  if($current -notin $allowed){throw "Unrecognized capture input: $name"}
  Copy-Item (Join-Path $PSScriptRoot "capture-$name-$phase.cs.txt") $target -Force
 }
}
try {
 foreach($phase in @('before','after')) {
  Install-Phase $phase
  $env:UH_BUILD_PROFILE_CAPTURE_OUTPUT=Join-Path $PSScriptRoot "build-profile-settings-$phase.png"
  $artifacts=Join-Path $PSScriptRoot "capture-settings-gui-scope-$phase"
  & $pwsh -NoProfile -File (Join-Path $repository 'scripts/unity/run-ci-tests.ps1') -UnityVersion '6000.6.7f1' -TestMode editmode -EnableEditorGraphics -AssemblyNames 'WallstopStudios.UnityHelpers.Tests.Editor.Capture' -TestFilter 'BuildProfileSettingsCaptureTests' -TestCategory '!Performance;!Stress' -RepoRoot $repository -ProjectPath $project -ArtifactsPath $artifacts -UnityEditorPath (Join-Path ${env:ProgramFiles} 'Unity/Hub/Editor/6000.6.7f1/Editor/Unity.exe') *> (Join-Path $PSScriptRoot "capture-settings-$phase-driver.log")
  if($LASTEXITCODE -ne 0){throw "Settings capture $phase failed $LASTEXITCODE"}
  [xml]$xml=Get-Content(Join-Path $artifacts 'results.xml') -Raw
  $cases=@($xml.SelectNodes('//test-case'))
  if($cases.Count -ne 1 -or $cases[0].result -ne 'Passed' -or @($xml.SelectNodes('//test-suite[@result="Failed"]')).Count){throw 'Missing or failed capture case/suite'}
  $receipt=Get-Content(Join-Path $artifacts 'unity.execution-diagnostics.json') -Raw|ConvertFrom-Json
  if($receipt.Process.RawExitCode -ne 0 -or -not $receipt.Process.StandardOutputEndObserved -or -not $receipt.Process.StandardErrorEndObserved -or $receipt.Process.OutputDrainStopped){throw 'Unhealthy capture process'}
 }
 $code=0
} catch { $_|Out-String|Set-Content(Join-Path $PSScriptRoot 'capture-settings-gui-scope-controller.log') }
finally {
 try {Install-Phase 'after'} catch {$code=1;$_|Out-String|Set-Content(Join-Path $PSScriptRoot 'capture-settings-gui-scope-restore-error.log')}
 @{exitCode=$code;completedUtc=[DateTime]::UtcNow}|ConvertTo-Json|Set-Content(Join-Path $PSScriptRoot 'capture-settings-gui-scope-result.json')
}
exit $code
